  width: 100%; height: 100%; padding: 8px;
  &::placeholder { color: var(--text-secondary-color); }
}
  & .altTextSpinner { display: none; position: absolute; width: 16px; height: 16px; inset-inline-start: 8px; inset-block-start: 8px; mask-size: cover; background-color: var(--text-secondary-color); pointer-events: none; }
  &.loading {
  & textarea::placeholder { color: transparent; }
  & .altTextSpinner { display: inline-block; mask-image: var(--new-alt-text-spinner-icon); }
}
}
  & #newAltTextDescription { font-size: 11px; }
