  &::before { content: ""; display: inline-block; width: 17px; height: 16px; mask-image: var(--new-alt-text-ai-disclaimer-icon); mask-size: cover; background-color: var(--text-secondary-color); flex: 1 0 auto; }
}
}
  & #newAltTextDownloadModel {
